typedef struct AcosConsts {
    double one;      /* 0x00 1.0 */
    double pi;       /* 0x08 */
    double pio2Hi;   /* 0x10 pi/2 high part */
    double pio2Lo;   /* 0x18 pi/2 low part */
    double pS0;      /* 0x20 */
    double pS1;      /* 0x28 */
    double pS2;      /* 0x30 */
    double pS3;      /* 0x38 */
    double pS4;      /* 0x40 */
    double pS5;      /* 0x48 */
    double qS1;      /* 0x50 */
    double qS2;      /* 0x58 */
    double qS3;      /* 0x60 */
    double qS4;      /* 0x68 */
    double zero;     /* 0x70 0.0 */
    double half;     /* 0x78 0.5 */
    double two;      /* 0x80 2.0 */
} AcosConsts;

typedef unsigned int uint32_t;

typedef uint32_t u32;

typedef struct CoreObject {
    struct CoreObject *prev;   /* 0x00 previous sibling (the chain tail when it was linked), NULL for the first */
    struct CoreObject *next;   /* 0x04 next sibling, NULL at the end */
    u32 unk08;                 /* 0x08 cleared by the constructor */
    u32 id;                    /* 0x0c unique id: ++g_coreObjectCounter at construction */
    struct CoreObjectList *list; /* 0x10 owning CoreObjectList (set by CoreObjectListAppend), NULL otherwise; cleared by the constructor */
    const void *vtable;        /* 0x14 &0x08af5394 for the base class; subclasses overwrite it (textures use 0x08af5864) */
} CoreObject;

typedef unsigned char uint8_t;

typedef uint8_t u8;

typedef int int32_t;

typedef int32_t s32;

typedef struct CoreNode {
    struct CoreNode *prev;          /* 0x00 previous sibling (or the anchor it was inserted after), NULL at the head */
    struct CoreNode *next;          /* 0x04 next sibling, NULL at the tail */
    u32 unk08;                      /* 0x08 cleared by the constructor; sound objects reuse it as a slot back-reference */
    u32 id;                         /* 0x0c unique id: ++g_coreNodeCounter at construction */
    struct CoreNodeOwner *owner;    /* 0x10 list owner this node was appended to by CoreNodeOwnerAppend, NULL otherwise */
    struct CoreNodeGroup *group;    /* 0x14 group header this node was added to by CoreNodeGroupAppend, NULL otherwise */
    u8 pad18[8];                    /* 0x18 unused by the base class */
    const void *vtable;             /* 0x20 &0x08af53a4 for the base class; every derived constructor overwrites it */
} CoreNode;

typedef struct SndEmitterProfile {
    s32 key;        /* 0x00 profile key, -1 .. -6; the id-range table g_soundProfileRanges maps sound ids to a key */
    char *name;     /* 0x04 Shift-JIS display name (editor label) */
    s32 shape;      /* 0x08 distance model: 0 = none (always audible), 1 = point (distance to posA), 2 = segment posA..posB */
    s32 curve;      /* 0x0c falloff curve id for SndApplyFalloffCurve (-1 = linear 1 - t, -3 = circular, 1 = ease) */
    float volNear;  /* 0x10 volume term at normalised distance 0 */
    float volFar;   /* 0x14 volume term at the audible radius */
    float radius;   /* 0x18 audible radius in world units; the emitter is silent beyond it */
} SndEmitterProfile;

typedef struct SndEmitter {
    s32 soundId;       /* 0x00 sound id passed to SndManagerPlay: bits 27..31 = SndManager group slot (SndManagerFindGroupSlot), bits 20..26 = sound group id (index into the seGRP_* table), bits 0..19 = cue */
    s32 handle;        /* 0x04 SndManager voice handle, -1 = not playing */
    float *src;        /* 0x08 live position source: 3 floats copied to posA each frame (6 floats / two vec3 when params->shape == 2); NULL = frozen */
    SndEmitterProfile *params; /* 0x0c attenuation profile chosen by SndEmitterGetProfile: shape (0 none, 1 point, 2 segment), falloff curve id (SndApplyFalloffCurve), volNear/volFar and the audible radius */
    float posA[3];     /* 0x10 current position (segment start for shape 2) */
    float posB[3];     /* 0x1c segment end position (shape 2 only) */
    float volume;      /* 0x28 last volume sent to the manager (0..127 scale applied by SndManagerSetVolume) */
    float pan;         /* 0x2c last pan sent to the manager */
    u8 silenced;       /* 0x30 set by the per-group arbiter: this emitter is not the nearest in its group, so no voice is kept */
    u8 released;       /* 0x31 owner has let go of the emitter (source pointer cleared); it is freed once the voice ends */
    u8 autoFree;       /* 0x32 free the emitter record when its voice ends */
    u8 pad33;          /* 0x33 */
    s32 repeat;        /* 0x34 remaining (re)starts; decremented while playing, 0 = stop at end of range */
    s32 state38;       /* 0x38 cleared to 0 when < 1, +1 while active; exact meaning not determined */
    s32 groupCount;    /* 0x3c number of audible emitters in the same exclusion group (set by SndEmitterAssignGroups) */
    float targetVolume;/* 0x40 distance-attenuated volume before group sharing */
    float groupVolSum; /* 0x44 sum of targetVolume over the group (set by SndEmitterAssignGroups) */
} SndEmitter;

typedef struct SndObject {
    CoreNode node;          /* 0x00 base header; vtable at 0x20 = 0x08af525c (the base ctor leaves 0x08af53a4 until SndObjectInit overwrites it) */
    u8 alive;               /* 0x24 1 after SndObjectInit; cleared by SndObjectDetachEmitters = "being shut down", SndObjectUpdate then drains and frees the object */
    u8 pad25[3];            /* 0x25 */
    SndEmitter **emitters;  /* 0x28 array of emitterCount SndEmitter pointers, NULL = free slot (from g_soundObjectSlotPool or the heap) */
    s32 emitterCount;       /* 0x2c number of slots in emitters, the second argument of SndObjectInit */
    float *src;             /* 0x30 position source handed to every emitter created through this object (emitter->src); NULL until SndObjectSetPosPtr/SndObjectSetPos */
    float posData[3];       /* 0x34 inline x,y,z written by SndObjectSetPos (src then points here) */
} SndObject;

