typedef struct IoDiscSimple {
    s32 state;                    /* +0x00 request state: 0 idle, 1 open, 2 get size, 3 wait buffer, 4/5 read, 6 close, 7/8, 9 suspended */
    s32 mode;                     /* +0x04 0 read, 1 rewind, 2 size only / get sector */
    u8 streamed;                  /* +0x08 `IoDiscRequestRead` `streamed` */
    u8 asyncIssued;                /* +0x09 set when an async call was issued successfully */
    u8 asyncPending;              /* +0x0a 1 while an async I/O call is outstanding */
    u8 busy;                      /* +0x0b request accepted, not yet acknowledged (`IoDiscFinishRequest`) */
    u8 idle;                      /* +0x0c `IoDiscIsIdle` */
    u8 destFromLow;               /* +0x0d placement of a reader-allocated dest: 0 high (`dest` was NULL), 1 low (`dest` was 1); `IoDiscSimpleStateGetSize` */
    u8 destResolved;              /* +0x0e set by `IoDiscSimpleStateGetSize` once `dest` holds a buffer; a re-run of that state releases it. Cleared by the request setters */
    u8 _unk0f;
    char *path;                   /* +0x10 requested path */
    SceUID fd;                    /* +0x14 async file descriptor; -1 when closed */
    SceInt64 asyncResult;         /* +0x18 sceIoPollAsync result */
    s32 result;                   /* +0x20 last I/O result (low word of asyncResult or a direct return) */
    void *dest;                   /* +0x24 destination buffer; (void *)-1 = allocate */
    u32 size;                     /* +0x28 file size (`IoDiscGetSize`) */
    s32 streamBytes;                /* +0x2c bytes streamed so far; cleared with each request */
    s32 writeIndex;               /* +0x30 next bufNodes slot to fill */
    s32 readIndex;                /* +0x34 next bufNodes slot to hand out */
    IoDiscBufNode *bufNodes[2];   /* +0x38 */
    IoDiscBufNode *curNode;       /* +0x40 node being filled */
    CoreLock *lock;               /* +0x44 "Mutex_CODiscSimple" LwMutex */
    u8 errorFlags;                /* +0x48 `IoDiscSetErrorFlags` */
    u8 openDecided;               /* +0x49 `IoDiscGetOpenResult` */
    u8 openOk;                    /* +0x4a */
    u8 _unk4b[0x95];
    u8 suspendAfterClose;         /* +0xe0 `IoDiscSimpleStateClose` goes to state 9 after the close; cleared by the request setters, never set in known code */
    u8 powerSuspend;              /* +0xe1 `IoDiscSetPowerSuspend` */
    u8 dataLoaded;                   /* +0xe2 set by `IoDiscSimpleStateRead` */
    u8 _unke3;
    s32 medium;                   /* +0xe4 1 = disc, 2 = memory stick */
    s32 msError;                  /* +0xe8 `IoDiscSimpleUpdate` sets 1 on a memory-stick error; cleared by the request setters */
    u8 abortClose;                /* +0xec forces the close state (`IoDiscSimpleUpdate`) */
    u8 resumeRequested;           /* +0xed `IoDiscRequestResume` */
    u8 _unkee[0x2];
    void *allocator;              /* +0xf0 `IoDiscSetAllocator`; vtable entry 1 (+0x8) allocates the file buffer (size, 0, 0), entry 2 (+0x10) frees it */
    u8 abortFlag;                    /* +0xf4 `IoDiscSetFlagF4`; abort for `IoDiscSimpleStateOpen` */
    u8 _unkf5[0x3];
    s32 error;                    /* +0xf8 `IoDiscGetError` / `IoDiscSetError` */
    u32 lba;                      /* +0xfc file start sector (`IoDiscGetLba`) */
    const VtblEntry *vtbl;        /* +0x100 0x08af5894 */
    u8 _unk104[0x4];
} IoDiscSimple;

