typedef struct UiTween {
    union {
        u8 _pad_00[0x14];   /* 0x00 not touched by the Ui* tween functions, see Notes */
        struct {
            u8 _pad_s00[7]; /* 0x00 */
            u8 toggle07;    /* 0x07 0/1 direction byte of slot owners: UiPulse.waiting, UiEquipSpinMarker shrink(0)/grow(1) */
            u8 type08;      /* 0x08 per-cell model type byte of the collection cell records (UiCollectionSphereCell.type); cleared by UiCollectionFigureStartCellModels */
            u8 _pad_s09[2]; /* 0x09 */
            u8 delay0b;     /* 0x0b frame countdown before the slot's tween runs: UiPulse hold counter, entry stagger of UiBattleModeSelectBeginEntries (0, 2) / UiBattleModeSelectStepEntries (4) */
            u8 cycle0c;     /* 0x0c step counter of slot owners: UiEquipAnimateUnknownMarkers index (0..4) into its five extra X offsets */
            u8 _pad_s0d[2]; /* 0x0d */
            u8 fadingOut0f; /* 0x0f 0/1 direction of the main-menu item-label alpha pulse: 0 = alpha rising, 1 = falling (UiMainMenuPulseItemLabel, cleared by UiMainMenuShowItemLabel) */
        };
    };
    union {
        struct {
            s16 slideStart; /* 0x14 start of the X (flags & 4) or Y (flags & 8) slide, whole pixels */
            s16 slideEnd;   /* 0x16 end position of the slide */
        };
        float plateFromX;   /* 0x14 float view: sprite X when the plate slide starts (UiEquipAnimateBakuganPlates) */
    };
    union {
        struct {
            s16 slideDelta; /* 0x18 slideEnd - slideStart */
            union {
                u8 _pad_1a[2];  /* 0x1a alignment for the tween functions */
                s16 moveToY;    /* 0x1a 4th s16 of the collection detail moves (UiCollectionCardStartMoveToZoom): +0x14/+0x16 from x/y, +0x18/+0x1a to x/y */
            };
        };
        float plateRestX;   /* 0x18 float view: resting X of the plate (UiEquip.markerBasePos[p][0], UiEquipAnimateBakuganPlates) */
    };
    float t;            /* 0x1c progress 0..1, reset to 0 by UiTweenBegin, += 1/frames per UiTweenUpdate */
    float startAlpha;   /* 0x20 snapshot of GfxSprite.alpha (flags & 1) */
    float startScale;   /* 0x24 snapshot of GfxSprite.scaleX (flags & 2) */
} UiTween;

